import { tv, type VariantProps } from "@/lib/beton/tv";

export const avatar = tv({
  slots: {
    root: [
      "relative inline-flex shrink-0 select-none items-center justify-center overflow-hidden",
      "rounded-md border-3 border-border align-middle font-display font-extrabold uppercase text-foreground",
    ],
    image: "size-full object-cover",
    fallback: "flex size-full items-center justify-center",
  },
  variants: {
    variant: {
      primary: { root: "bg-primary" },
      secondary: { root: "bg-secondary" },
      ghost: { root: "bg-raised" },
      danger: { root: "bg-danger" },
    },
    size: {
      sm: { root: "size-8 border-2 text-xs" },
      md: { root: "size-11 text-sm" },
      lg: { root: "size-16 text-xl" },
    },
  },
  defaultVariants: {
    variant: "secondary",
    size: "md",
  },
});

export type AvatarVariants = VariantProps<typeof avatar>;

"use client";

import { Avatar as BaseAvatar } from "@base-ui/react/avatar";
import { avatar, type AvatarVariants } from "@/lib/beton/recipes/avatar.recipe";
import type { ReactNode } from "react";

export interface AvatarProps
  extends Omit<BaseAvatar.Root.Props, "className" | "children">, AvatarVariants {
  className?: string;
  /** Image URL. When missing or broken, the fallback is shown. */
  src?: string;
  /** Describes the person or entity. Used as the image alt text and the fallback's accessible name. */
  alt: string;
  /** Shown while the image loads or when it fails. Defaults to initials derived from `alt`. */
  fallback?: ReactNode;
  /** Milliseconds to wait before showing the fallback, to avoid a flash on fast connections. */
  fallbackDelay?: number;
}

export function initials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  const first = parts[0]?.[0] ?? "";
  const last = parts.length > 1 ? (parts[parts.length - 1]?.[0] ?? "") : "";
  return (first + last).toUpperCase();
}

export function Avatar({
  variant = "secondary",
  size = "md",
  src,
  alt,
  fallback,
  fallbackDelay,
  className,
  ...props
}: AvatarProps) {
  const styles = avatar({ variant, size });
  return (
    <BaseAvatar.Root
      {...props}
      data-variant={variant}
      data-size={size}
      className={styles.root({ class: className })}
    >
      {src ? <BaseAvatar.Image src={src} alt={alt} className={styles.image()} /> : null}
      <BaseAvatar.Fallback
        delay={src ? fallbackDelay : undefined}
        role="img"
        aria-label={alt}
        className={styles.fallback()}
      >
        <span aria-hidden="true">{fallback ?? initials(alt)}</span>
      </BaseAvatar.Fallback>
    </BaseAvatar.Root>
  );
}
